1	// Meeting-room booking server: JSON API, browser page, one JSON data file.
2	// Node.js built-ins only.
3	import http from 'node:http';
4	import fs from 'node:fs';
5	import path from 'node:path';
6	import { fileURLToPath } from 'node:url';
7	
8	const HOST = '127.0.0.1';
9	const DEFAULT_PORT = 3000;
10	const MAX_PORT = 65535;
11	const MAX_BODY_BYTES = 10000;
12	const ROOMS = Object.freeze(['Aurora', 'Borealis', 'Cosmos']);
13	const BOOKING_KEYS = Object.freeze(['id', 'room', 'title', 'date', 'start', 'end']);
14	const JSON_TYPE = 'application/json; charset=utf-8';
15	const PUBLIC_DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), 'public');
16	const PAGES = Object.freeze({
17	  '/': { file: 'index.html', type: 'text/html; charset=utf-8' },
18	  '/app.js': { file: 'app.js', type: 'text/javascript; charset=utf-8' },
19	});
20	const DELETE_ROUTE = /^\/api\/bookings\/[^/]+$/;
21	const ID_PATTERN = /^[1-9][0-9]*$/;
22	const DATE_PATTERN = /^([0-9]{4})-([0-9]{2})-([0-9]{2})$/;
23	const TIME_PATTERN = /^([0-9]{2}):([0-9]{2})$/;
24	
25	const MSG = Object.freeze({
26	  contentType: 'content type must be application/json',
27	  tooLarge: 'body too large',
28	  notObject: 'body must be a JSON object',
29	  room: 'room must be one of Aurora, Borealis, Cosmos',
30	  title: 'title must be 1 to 80 characters',
31	  date: 'date must be a valid YYYY-MM-DD date',
32	  start: 'start must be HH:MM',
33	  end: 'end must be HH:MM',
34	  order: 'end must be after start',
35	  bookingNotFound: 'booking not found',
36	  notFound: 'not found',
37	  method: 'method not allowed',
38	  internal: 'internal error',
39	});
40	
41	/** Thrown for a request that must get a specific error reply. */
42	class HttpError extends Error {
43	  constructor(status, message) {
44	    super(message);
45	    this.status = status;
46	  }
47	}
48	
49	// ---------- field validation (shared by the API and the data-file check) ----------
50	
51	const isPlainObject = (value) =>
52	  typeof value === 'object' && value !== null && !Array.isArray(value);
53	
54	function isValidDate(value) {
55	  if (typeof value !== 'string') return false;
56	  const match = DATE_PATTERN.exec(value);
57	  if (!match) return false;
58	  const [year, month, day] = match.slice(1).map(Number);
59	  if (year < 2000 || year > 2099 || month < 1 || month > 12 || day < 1) return false;
60	  const febDays = year % 4 === 0 ? 29 : 28;
61	  const monthDays = [31, febDays, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
62	  return day <= monthDays[month - 1];
63	}
64	
65	function isValidTime(value) {
66	  if (typeof value !== 'string') return false;
67	  const match = TIME_PATTERN.exec(value);
68	  return match !== null && Number(match[1]) <= 23 && Number(match[2]) <= 59;
69	}
70	
71	const isValidTitle = (value) =>
72	  typeof value === 'string' && value.trim().length >= 1 && value.trim().length <= 80;
73	
74	const overlaps = (a, b) =>
75	  a.room === b.room && a.date === b.date && a.start < b.end && b.start < a.end;
76	
77	/** Rules 4-9 on a parsed body; returns the new booking fields or throws HttpError. */
78	function validateFields(body) {
79	  if (typeof body.room !== 'string' || !ROOMS.includes(body.room)) throw new HttpError(400, MSG.room);
80	  if (!isValidTitle(body.title)) throw new HttpError(400, MSG.title);
81	  if (!isValidDate(body.date)) throw new HttpError(400, MSG.date);
82	  if (!isValidTime(body.start)) throw new HttpError(400, MSG.start);
83	  if (!isValidTime(body.end)) throw new HttpError(400, MSG.end);
84	  if (!(body.end > body.start)) throw new HttpError(400, MSG.order);
85	  return { room: body.room, title: body.title.trim(), date: body.date, start: body.start, end: body.end };
86	}
87	
88	// ---------- data file ----------
89	
90	const emptyState = () => Object.freeze({ nextId: 1, bookings: Object.freeze([]) });
91	
92	function isStoredBooking(b) {
93	  if (!isPlainObject(b)) return false;
94	  const keys = Object.keys(b);
95	  if (keys.length !== BOOKING_KEYS.length || !BOOKING_KEYS.every((k) => keys.includes(k))) return false;
96	  return Number.isSafeInteger(b.id) && b.id >= 1 && ROOMS.includes(b.room)
97	    && isValidTitle(b.title) && b.title === b.title.trim()
98	    && isValidDate(b.date) && isValidTime(b.start) && isValidTime(b.end) && b.end > b.start;
99	}
100	
101	/** Strict check that `data` is exactly the layout this server writes. */
102	function isValidLayout(data) {
103	  if (!isPlainObject(data)) return false;
104	  const keys = Object.keys(data);
105	  if (keys.length !== 2 || !keys.includes('nextId') || !keys.includes('bookings')) return false;
106	  const { nextId, bookings } = data;
107	  if (!Number.isSafeInteger(nextId) || nextId < 1 || !Array.isArray(bookings)) return false;
108	  if (!bookings.every(isStoredBooking)) return false;
109	  const ids = new Set(bookings.map((b) => b.id));
110	  if (ids.size !== bookings.length || bookings.some((b) => b.id >= nextId)) return false;
111	  return !bookings.some((b, i) => bookings.slice(i + 1).some((other) => overlaps(b, other)));
112	}
113	
114	/** Reads the data file once; returns the state or null when it cannot be used. */
115	function loadState(filePath) {
116	  let text;
117	  try {
118	    text = fs.readFileSync(filePath, 'utf8');
119	  } catch (err) {
120	    return err.code === 'ENOENT' ? emptyState() : null;
121	  }
122	  let data;
123	  try {
124	    data = JSON.parse(text);
125	  } catch {
126	    return null;
127	  }
128	  if (!isValidLayout(data)) return null;
129	  return Object.freeze({ nextId: data.nextId, bookings: Object.freeze(data.bookings.map((b) => Object.freeze({ ...b }))) });
130	}
131	
132	/** Writes a temp file beside the data file, then renames it over, so a failed save leaves the old file intact. */
133	async function saveState(filePath, state) {
134	  const tempPath = `${filePath}.${process.pid}.tmp`;
135	  try {
136	    await fs.promises.writeFile(tempPath, JSON.stringify({ nextId: state.nextId, bookings: state.bookings }));
137	    await fs.promises.rename(tempPath, filePath);
138	  } catch (err) {
139	    await fs.promises.rm(tempPath, { force: true }).catch(() => {}); // best-effort cleanup; the save error below is what matters
140	    throw err;
141	  }
142	}
143	
144	// ---------- request plumbing ----------
145	
146	/** Reads the whole body; keeps at most MAX_BODY_BYTES + 1 bytes but counts every byte received. */
147	function readBody(req) {
148	  return new Promise((resolve, reject) => {
149	    const chunks = [];
150	    let kept = 0;
151	    let total = 0;
152	    req.on('data', (chunk) => {
153	      total += chunk.length;
154	      if (kept <= MAX_BODY_BYTES) {
155	        chunks.push(chunk);
156	        kept += chunk.length;
157	      }
158	    });
159	    req.on('end', () => resolve({ buffer: Buffer.concat(chunks), size: total }));
160	    req.on('error', reject);
161	    req.on('aborted', () => reject(new Error('request aborted')));
162	  });
163	}
164	
165	function send(res, status, payload) {
166	  if (status === 204) {
167	    res.writeHead(204);
168	    res.end();
169	    return;
170	  }
171	  const body = JSON.stringify(payload);
172	  res.writeHead(status, { 'Content-Type': JSON_TYPE, 'Content-Length': Buffer.byteLength(body) });
173	  res.end(body);
174	}
175	
176	const sendError = (res, status, message) => send(res, status, { error: message });
177	
178	function isJsonContentType(header) {
179	  if (typeof header !== 'string') return false;
180	  const media = header.split(';')[0].replace(/^[ \t]+|[ \t]+$/g, '');
181	  return media.toLowerCase() === 'application/json';
182	}
183	
184	function parseObjectBody(buffer) {
185	  let parsed;
186	  try {
187	    parsed = JSON.parse(buffer.toString('utf8'));
188	  } catch {
189	    throw new HttpError(400, MSG.notObject);
190	  }
191	  if (!isPlainObject(parsed)) throw new HttpError(400, MSG.notObject);
192	  return parsed;
193	}
194	
195	function compareBookings(a, b) {
196	  if (a.date !== b.date) return a.date < b.date ? -1 : 1;
197	  if (a.start !== b.start) return a.start < b.start ? -1 : 1;
198	  return ROOMS.indexOf(a.room) - ROOMS.indexOf(b.room);
199	}
200	
201	// ---------- application ----------
202	
203	function createApp(dataFile, initialState) {
204	  let state = initialState;
205	
206	  function listBookings(query) {
207	    const params = new URLSearchParams(query);
208	    let bookings = state.bookings;
209	    if (params.has('date')) {
210	      const date = params.get('date');
211	      if (!isValidDate(date)) throw new HttpError(400, MSG.date);
212	      bookings = bookings.filter((b) => b.date === date);
213	    }
214	    return { status: 200, payload: { bookings: [...bookings].sort(compareBookings) } };
215	  }
216	
217	  async function createBooking(req, body) {
218	    if (!isJsonContentType(req.headers['content-type'])) throw new HttpError(415, MSG.contentType);
219	    if (body.size > MAX_BODY_BYTES) throw new HttpError(413, MSG.tooLarge);
220	    const fields = validateFields(parseObjectBody(body.buffer));
221	    const clashes = state.bookings.filter((b) => overlaps(b, fields));
222	    if (clashes.length > 0) {
223	      const first = clashes.reduce((a, b) => (b.start < a.start ? b : a));
224	      throw new HttpError(409, `room is already booked from ${first.start} to ${first.end}`);
225	    }
226	    const booking = Object.freeze({ id: state.nextId, ...fields });
227	    await commit({ nextId: state.nextId + 1, bookings: [...state.bookings, booking] });
228	    return { status: 201, payload: booking };
229	  }
230	
231	  async function deleteBooking(rawId) {
232	    const id = ID_PATTERN.test(rawId) && Number.isSafeInteger(Number(rawId)) ? Number(rawId) : NaN;
233	    if (!state.bookings.some((b) => b.id === id)) throw new HttpError(404, MSG.bookingNotFound);
234	    await commit({ nextId: state.nextId, bookings: state.bookings.filter((b) => b.id !== id) });
235	    return { status: 204 };
236	  }
237	
238	  /** Saves the candidate state first; memory changes only when the save succeeded. */
239	  async function commit(candidate) {
240	    const next = Object.freeze({ nextId: candidate.nextId, bookings: Object.freeze(candidate.bookings) });
241	    await saveState(dataFile, next);
242	    state = next;
243	  }
244	
245	  return { listBookings, createBooking, deleteBooking };
246	}
247	
248	async function servePage(page) {
249	  const content = await fs.promises.readFile(path.join(PUBLIC_DIR, page.file));
250	  return { status: 200, page: { type: page.type, content } };
251	}
252	
253	function splitTarget(target) {
254	  const mark = target.indexOf('?');
255	  return mark === -1
256	    ? { pathname: target, query: '' }
257	    : { pathname: target.slice(0, mark), query: target.slice(mark + 1) };
258	}
259	
260	function requireMethod(method, allowed) {
261	  if (method !== allowed) throw new HttpError(405, MSG.method);
262	}
263	
264	/** Routes one request (body already read) to its result, or throws HttpError. */
265	async function route(app, req, body) {
266	  const { pathname, query } = splitTarget(req.url);
267	  const { method } = req;
268	  if (Object.hasOwn(PAGES, pathname)) {
269	    requireMethod(method, 'GET');
270	    return servePage(PAGES[pathname]);
271	  }
272	  if (pathname === '/api/rooms') {
273	    requireMethod(method, 'GET');
274	    return { status: 200, payload: { rooms: [...ROOMS] } };
275	  }
276	  if (pathname === '/api/bookings') {
277	    if (method === 'GET') return app.listBookings(query);
278	    if (method === 'POST') return app.createBooking(req, body);
279	    throw new HttpError(405, MSG.method);
280	  }
281	  if (DELETE_ROUTE.test(pathname)) {
282	    requireMethod(method, 'DELETE');
283	    return app.deleteBooking(pathname.slice('/api/bookings/'.length));
284	  }
285	  throw new HttpError(404, MSG.notFound);
286	}
287	
288	function writeResult(res, result) {
289	  if (result.page) {
290	    res.writeHead(200, { 'Content-Type': result.page.type, 'Content-Length': result.page.content.length });
291	    res.end(result.page.content);
292	    return;
293	  }
294	  send(res, result.status, result.payload);
295	}
296	
297	/** Logs an unexpected failure as one stderr line (stdout is reserved for the listening line). */
298	function logUnexpected(err) {
299	  const detail = err instanceof Error ? `${err.name}: ${err.message}` : String(err);
300	  process.stderr.write(`request failed: ${detail.replace(/\s+/g, ' ')}\n`);
301	}
302	
303	function writeFailure(res, err) {
304	  if (!(err instanceof HttpError)) logUnexpected(err);
305	  if (res.headersSent) {
306	    res.destroy();
307	    return;
308	  }
309	  if (err instanceof HttpError) sendError(res, err.status, err.message);
310	  else sendError(res, 500, MSG.internal);
311	}
312	
313	/** Serialises request handling so concurrent requests act as if handled one at a time. */
314	function createHandler(app) {
315	  let queue = Promise.resolve();
316	  return (req, res) => {
317	    // A failed write to a vanished client must not crash the server; nothing else to do.
318	    res.on('error', () => {});
319	    readBody(req).then(
320	      (body) => {
321	        queue = queue.then(() => route(app, req, body)
322	          .then((result) => writeResult(res, result), (err) => writeFailure(res, err))
323	          .catch((err) => {
324	            logUnexpected(err);
325	            res.destroy();
326	          }));
327	      },
328	      () => res.destroy(), // client aborted before sending its body: there is no one to reply to
329	    );
330	  };
331	}
332	
333	// ---------- startup ----------
334	
335	function fail(line) {
336	  process.stderr.write(`${line}\n`);
337	  process.exit(1);
338	}
339	
340	function parsePort(raw) {
341	  if (raw === undefined || raw === '') return DEFAULT_PORT;
342	  if (!/^[0-9]+$/.test(raw)) return null;
343	  const port = Number(raw);
344	  return port <= MAX_PORT ? port : null;
345	}
346	
347	function main() {
348	  const port = parsePort(process.env.PORT);
349	  if (port === null) fail(`invalid PORT ${JSON.stringify(process.env.PORT)}`);
350	  const dataName = process.env.DATA_FILE || 'bookings.json';
351	  const dataFile = path.resolve(process.cwd(), dataName);
352	  const state = loadState(dataFile);
353	  if (state === null) fail(`cannot read data file ${dataName}`);
354	
355	  const server = http.createServer(createHandler(createApp(dataFile, state)));
356	  server.on('clientError', (_err, socket) => {
357	    if (socket.writable) socket.end('HTTP/1.1 400 Bad Request\r\nConnection: close\r\n\r\n');
358	    else socket.destroy();
359	  });
360	  server.on('error', (err) => fail(`cannot listen on port ${port}: ${err.code || 'error'}`));
361	  server.listen(port, HOST, () => {
362	    process.stdout.write(`listening on http://${HOST}:${server.address().port}\n`);
363	  });
364	}
365	
366	main();
